"""The brazier's hand poses, posed with the user in fp_arms_posing.blend (tools/arms/brazier_poses.json), into the game:
scripts/Combat/BrazierPoses.gd. python3 tools/arms/export_brazier_poses.py"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
## Where the shoulder is, in the posing file's view.
SHOULDER = (0.183, -0.196, 0.103)

poses = json.load(open(os.path.join(HERE, "brazier_poses.json")))
lines = [
    "extends RefCounted",
    "## The brazier's hand poses, as posed in Blender: GENERATED by tools/arms/export_brazier_poses.py from tools/arms/brazier_poses.json. Don't edit.",
    "",
    "## Each is the hand bone in the eye's space (x back of the hand, y to the knuckles, z thumb side), and the way its elbow goes, from the middle of the arm.",
    "",
    "const POSES := {",
]


def vec(v):
    return "Vector3(%.4f, %.4f, %.4f)" % tuple(v)


for name, pose in poses.items():
    if name.startswith("_"):
        continue

    origin = pose["origin"]
    wrist = origin
    elbow = pose["elbow"]
    hint = [elbow[i] - (SHOULDER[i] + wrist[i]) * 0.5 for i in range(3)]
    lines.append('\t&"%s": {"at": %s, "x": %s, "y": %s, "z": %s, "elbow": %s},' % (name, vec(origin), vec(pose["x"]), vec(pose["y"]), vec(pose["z"]), vec(hint)))

lines += ["}", "", "## The chain grip: the fist, with the thumb clamped over the fingers. Each bone's turn from its rest (w, x, y, z).", "const THUMB := {"]

for bone, q in poses["_fingers"].items():
    lines.append('\t&"%s": Quaternion(%.4f, %.4f, %.4f, %.4f),' % (bone, q[1], q[2], q[3], q[0]))

lines += ["}", ""]
open(os.path.join(ROOT, "scripts/Combat/BrazierPoses.gd"), "w").write("\n".join(lines))
print("WROTE", len(poses), "poses")


# Possession: both hands.
poses = json.load(open(os.path.join(HERE, "possession_poses.json")))
lines = [
    "extends RefCounted",
    "## Possession's hands, as posed in Blender: GENERATED by tools/arms/export_brazier_poses.py from tools/arms/possession_poses.json. Don't edit.",
    "",
    "## Each hand: its bone in the eye's space (x, y to the knuckles, z), and the way its elbow goes.",
    "const POSES := {",
]


def hand(h):
    elbow = h["elbow"]
    hint = [elbow[i] - (h["shoulder"][i] + h["origin"][i]) * 0.5 for i in range(3)]
    return '{"at": %s, "x": %s, "y": %s, "z": %s, "elbow": %s}' % (vec(h["origin"]), vec(h["x"]), vec(h["y"]), vec(h["z"]), vec(hint))


for name, pose in poses.items():
    if not name.startswith("_"):
        lines.append('\t&"%s": {"fingers": &"%s", "r": %s, "l": %s},' % (name, pose["fingers"], hand(pose["r"]), hand(pose["l"])))

lines += ["}", "", "## The claw: bent back at the knuckle, hooked at the tips. Each bone's turn from its rest.", "const CLAW := {"]

for bone, q in poses["_claw"].items():
    lines.append('\t&"%s": Quaternion(%.4f, %.4f, %.4f, %.4f),' % (bone, q[1], q[2], q[3], q[0]))

lines += ["}", ""]
open(os.path.join(ROOT, "scripts/PlayerUtils/PossessionPoses.gd"), "w").write("\n".join(lines))
print("WROTE possession")
